// cursor.cpp — smooth cursor motion along a cubic Bezier via SendInput.
//
// Windows, C++17. Link: user32.lib, winmm.lib (pulled in via #pragma below).
//
// API:
//   cursor::CancelToken tok;
//   cursor::Result r = cursor::MoveTo(x, y, &tok);          // blocking
//
//   cursor::AsyncMove m = cursor::MoveToAsync(x, y);        // background thread
//   m.cancel();                                             // any time
//   cursor::Result r = m.wait();
//
// Coordinates are virtual-desktop pixels (same space as GetCursorPos), so
// multi-monitor setups with negative origins work. The process should be
// per-monitor DPI aware, or coordinates will be scaled by Windows.

#ifndef NOMINMAX
#define NOMINMAX
#endif
#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#include <windows.h>
#include <timeapi.h>

#include <algorithm>
#include <atomic>
#include <cmath>
#include <future>
#include <memory>
#include <random>
#include <thread>

#pragma comment(lib, "user32.lib")
#pragma comment(lib, "winmm.lib")

namespace cursor {

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
struct Config {
    int    minDurationMs  = 60;
    int    maxDurationMs  = 140;
    // Control-point perpendicular offset as a fraction of path length.
    double maxCurvature   = 0.25;
    // Clamp on the perpendicular offset in pixels (keeps long moves sane).
    double maxOffsetPx    = 200.0;
    // Apply smoothstep easing to the Bezier parameter.
    bool   easeInOut      = true;
};

enum class Result {
    Completed,   // reached (x, y)
    Cancelled,   // token was set mid-move; cursor left where it was
    Failed,      // GetCursorPos / SendInput failed (e.g. UIPI-blocked)
};

// ---------------------------------------------------------------------------
// Cancellation
// ---------------------------------------------------------------------------
class CancelToken {
public:
    void cancel() noexcept { flag_.store(true, std::memory_order_relaxed); }
    void reset()  noexcept { flag_.store(false, std::memory_order_relaxed); }
    bool cancelled() const noexcept { return flag_.load(std::memory_order_relaxed); }
private:
    std::atomic<bool> flag_{false};
};

// ---------------------------------------------------------------------------
// Internals
// ---------------------------------------------------------------------------
namespace detail {

struct Vec2 { double x, y; };

inline Vec2 Bezier(const Vec2& p0, const Vec2& p1, const Vec2& p2, const Vec2& p3, double t) {
    const double u  = 1.0 - t;
    const double b0 = u * u * u;
    const double b1 = 3.0 * u * u * t;
    const double b2 = 3.0 * u * t * t;
    const double b3 = t * t * t;
    return { b0 * p0.x + b1 * p1.x + b2 * p2.x + b3 * p3.x,
             b0 * p0.y + b1 * p1.y + b2 * p2.y + b3 * p3.y };
}

inline double Smoothstep(double t) { return t * t * (3.0 - 2.0 * t); }

inline std::mt19937& Rng() {
    thread_local std::mt19937 rng{ std::random_device{}() };
    return rng;
}

// Raise timer resolution to 1 ms for the lifetime of the object.
struct TimerResolution {
    TimerResolution()  { ok = (timeBeginPeriod(1) == TIMERR_NOERROR); }
    ~TimerResolution() { if (ok) timeEndPeriod(1); }
    bool ok = false;
};

struct Clock {
    Clock() { QueryPerformanceFrequency(&freq); QueryPerformanceCounter(&start); }
    double elapsedMs() const {
        LARGE_INTEGER now;
        QueryPerformanceCounter(&now);
        return double(now.QuadPart - start.QuadPart) * 1000.0 / double(freq.QuadPart);
    }
    LARGE_INTEGER freq{}, start{};
};

// Send an absolute move in virtual-desktop pixel coordinates.
inline bool SendAbsoluteMove(int px, int py) {
    const int vx = GetSystemMetrics(SM_XVIRTUALSCREEN);
    const int vy = GetSystemMetrics(SM_YVIRTUALSCREEN);
    const int vw = GetSystemMetrics(SM_CXVIRTUALSCREEN);
    const int vh = GetSystemMetrics(SM_CYVIRTUALSCREEN);
    if (vw <= 1 || vh <= 1) return false;

    px = std::clamp(px, vx, vx + vw - 1);
    py = std::clamp(py, vy, vy + vh - 1);

    // Map to 0..65535 across the virtual desktop. Rounding (not truncation)
    // so the pixel round-trips exactly.
    const LONG nx = static_cast<LONG>(std::lround(double(px - vx) * 65535.0 / double(vw - 1)));
    const LONG ny = static_cast<LONG>(std::lround(double(py - vy) * 65535.0 / double(vh - 1)));

    INPUT in{};
    in.type       = INPUT_MOUSE;
    in.mi.dx      = nx;
    in.mi.dy      = ny;
    in.mi.dwFlags = MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_VIRTUALDESK;
    return SendInput(1, &in, sizeof(INPUT)) == 1;
}

} // namespace detail

// ---------------------------------------------------------------------------
// Blocking move
// ---------------------------------------------------------------------------
inline Result MoveTo(int x, int y, const CancelToken* token = nullptr, const Config& cfg = {}) {
    using namespace detail;

    POINT cur;
    if (!GetCursorPos(&cur)) return Result::Failed;

    const Vec2 p0{ double(cur.x), double(cur.y) };
    const Vec2 p3{ double(x), double(y) };

    const double dx  = p3.x - p0.x;
    const double dy  = p3.y - p0.y;
    const double len = std::hypot(dx, dy);

    if (len < 1.0) {
        return SendAbsoluteMove(x, y) ? Result::Completed : Result::Failed;
    }

    // Random duration and curvature.
    auto& rng = Rng();
    const int lo = std::max(1, std::min(cfg.minDurationMs, cfg.maxDurationMs));
    const int hi = std::max(lo, cfg.maxDurationMs);
    const double durationMs = double(std::uniform_int_distribution<int>(lo, hi)(rng));

    std::uniform_real_distribution<double> curv(-cfg.maxCurvature, cfg.maxCurvature);
    std::uniform_real_distribution<double> along1(0.20, 0.40);
    std::uniform_real_distribution<double> along2(0.60, 0.80);

    // Unit perpendicular to the straight path.
    const double nx = -dy / len;
    const double ny =  dx / len;

    auto offset = [&](double frac) {
        return std::clamp(frac * len, -cfg.maxOffsetPx, cfg.maxOffsetPx);
    };
    const double o1 = offset(curv(rng));
    const double o2 = offset(curv(rng));
    const double a1 = along1(rng);
    const double a2 = along2(rng);

    const Vec2 p1{ p0.x + dx * a1 + nx * o1, p0.y + dy * a1 + ny * o1 };
    const Vec2 p2{ p0.x + dx * a2 + nx * o2, p0.y + dy * a2 + ny * o2 };

    TimerResolution timerRes;
    Clock clock;

    LONG lastX = cur.x, lastY = cur.y;
    for (;;) {
        if (token && token->cancelled()) return Result::Cancelled;

        const double elapsed = clock.elapsedMs();
        double t = std::min(1.0, elapsed / durationMs);
        const double s = cfg.easeInOut ? Smoothstep(t) : t;

        const Vec2 p = Bezier(p0, p1, p2, p3, s);
        const LONG px = std::lround(p.x);
        const LONG py = std::lround(p.y);

        if (px != lastX || py != lastY) {
            if (!SendAbsoluteMove(px, py)) return Result::Failed;
            lastX = px; lastY = py;
        }

        if (t >= 1.0) break;
        Sleep(1);
    }

    // Guarantee exact landing (rounding / clamping on the last step).
    if (lastX != x || lastY != y) {
        if (token && token->cancelled()) return Result::Cancelled;
        if (!SendAbsoluteMove(x, y)) return Result::Failed;
    }
    return Result::Completed;
}

// ---------------------------------------------------------------------------
// Async move with a cancel handle
// ---------------------------------------------------------------------------
class AsyncMove {
public:
    AsyncMove() = default;
    AsyncMove(AsyncMove&&) noexcept = default;
    AsyncMove& operator=(AsyncMove&& o) noexcept {
        if (this != &o) { cancelAndJoin(); token_ = std::move(o.token_); fut_ = std::move(o.fut_); }
        return *this;
    }
    AsyncMove(const AsyncMove&) = delete;
    AsyncMove& operator=(const AsyncMove&) = delete;

    ~AsyncMove() { cancelAndJoin(); }

    void cancel() noexcept { if (token_) token_->cancel(); }

    bool done() const {
        return fut_.valid() &&
               fut_.wait_for(std::chrono::seconds(0)) == std::future_status::ready;
    }

    Result wait() { return fut_.valid() ? fut_.get() : Result::Failed; }

private:
    friend AsyncMove MoveToAsync(int, int, const Config&);

    void cancelAndJoin() {
        if (fut_.valid()) { cancel(); fut_.wait(); }
    }

    std::shared_ptr<CancelToken> token_;
    std::future<Result>          fut_;
};

inline AsyncMove MoveToAsync(int x, int y, const Config& cfg = {}) {
    AsyncMove m;
    m.token_ = std::make_shared<CancelToken>();
    auto tok = m.token_;
    m.fut_ = std::async(std::launch::async, [x, y, cfg, tok] {
        return MoveTo(x, y, tok.get(), cfg);
    });
    return m;
}

} // namespace cursor

// ---------------------------------------------------------------------------
// Demo: build with -DCURSOR_DEMO
// ---------------------------------------------------------------------------
#ifdef CURSOR_DEMO
#include <cstdio>

int main() {
    SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);

    // Blocking move.
    cursor::Result r = cursor::MoveTo(800, 500);
    std::printf("blocking: %d\n", static_cast<int>(r));

    // Async move, cancelled halfway.
    auto m = cursor::MoveToAsync(200, 200);
    std::this_thread::sleep_for(std::chrono::milliseconds(40));
    m.cancel();
    std::printf("async:    %d\n", static_cast<int>(m.wait()));
    return 0;
}
#endif
